// android/ and ios/ are not in git: they are generated by `expo prebuild`
// (see README / INFO.md). The few things that used to be edited by hand in
// those folders live here instead, so every prebuild puts them back.
const fs = require("fs");
const path = require("path");
const {
  AndroidConfig,
  withAndroidManifest,
  withAppDelegate,
  withDangerousMod,
} = require("expo/config-plugins");

const POD_TARGET_MARKER = "# [withNativeTweaks] clamp pod deployment targets";
const POD_ARCH_MARKER = "# [withNativeTweaks] ensure new arch env for podspecs";

// react_native_post_install only raises a pod's deployment target up to the
// app's minimum (15.1) - it never lowers one. A pod whose podspec asks for
// more (e.g. 16.0) keeps compiling against it, which can weak-link APIs
// wrongly and crash through dyld at launch on iOS 15. Forcing every pod down
// to the app's own target turns that into a build-time availability error.
const POD_TARGET_BLOCK = `
    ${POD_TARGET_MARKER}
    app_deployment_target = podfile_properties['ios.deploymentTarget'] || '15.1'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = app_deployment_target
      end
    end
`;

const withPodfileTweaks = (config) =>
  withDangerousMod(config, [
    "ios",
    (cfg) => {
      const podfile = path.join(cfg.modRequest.platformProjectRoot, "Podfile");
      if (!fs.existsSync(podfile)) return cfg;

      let contents = fs.readFileSync(podfile, "utf8");

      // Set RCT_NEW_ARCH_ENABLED at the top so any podspecs requiring it
      // during use_native_modules! will find it set.
      if (!contents.includes(POD_ARCH_MARKER)) {
        contents = contents.replace(
          /(platform :ios[^\n]*\n)/,
          `$1${POD_ARCH_MARKER}\nENV['RCT_NEW_ARCH_ENABLED'] ||= '1'\n`
        );
      }

      if (!contents.includes(POD_TARGET_MARKER)) {
        // Right after the react_native_post_install(...) call, inside post_install.
        const next = contents.replace(
          /(react_native_post_install\([\s\S]*?\n\s*\)\n)/,
          `$1${POD_TARGET_BLOCK}`
        );
        if (next === contents) {
          console.warn("[withNativeTweaks] react_native_post_install not found in Podfile; deployment targets not clamped");
        } else {
          contents = next;
        }
      }

      fs.writeFileSync(podfile, contents);
      return cfg;
    },
  ]);

// Large screens (tablets, foldables, split screen): Google Play's large
// screen quality rules want the activity resizeable even though the app
// itself stays portrait.
const withResizeableActivity = (config) =>
  withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    activity.$["android:resizeableActivity"] = "true";
    return cfg;
  });

// CI signs the APK with this keystore. It is kept outside android/ so every
// build - whichever machine prebuilt the project - has the same signature;
// with a different one, Android refuses to install the APK over an existing
// install.
// Incoming calls (Zalo / Messenger style lockscreen popup): allow MainActivity
// to wake the screen and display over the lockscreen when a full-screen intent
// or call push arrives.
const withIncomingCallLockscreenFlags = (config) =>
  withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    activity.$["android:showWhenLocked"] = "true";
    activity.$["android:turnScreenOn"] = "true";
    activity.$["android:showOnLockScreen"] = "true";
    activity.$["android:inheritShowWhenLocked"] = "true";

    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.USE_FULL_SCREEN_INTENT");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.WAKE_LOCK");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.VIBRATE");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.FOREGROUND_SERVICE");

    return cfg;
  });

const withStableDebugKeystore = (config) =>
  withDangerousMod(config, [
    "android",
    (cfg) => {
      const source = path.join(cfg.modRequest.projectRoot, "keystores", "debug.keystore");
      const target = path.join(cfg.modRequest.platformProjectRoot, "app", "debug.keystore");
      if (fs.existsSync(source) && fs.existsSync(path.dirname(target))) {
        fs.copyFileSync(source, target);
      }
      return cfg;
    },
  ]);

const IMAGE_CLASSES_MARKER = "[withNativeTweaks] image module classes";

// React Native's image modules ("ImageLoader", ...) are not in the class table
// open-source builds use, so the TurboModule manager finds them by name:
// NSClassFromString("ImageLoader") first, "RCTImageLoader" only if that is nil.
// On iOS 15 the first lookup returns some other class called ImageLoader, the
// module is then reported as "could not be found", and the app failed at
// launch (React Native's Image needs it; iOS 16+ was fine). Naming the classes
// in the app's delegate skips that lookup. A plain @objc method, not an
// override: Swift does not see RCTTurboModuleManagerDelegate (C++ only), but
// React Native calls the selector at runtime.
const IMAGE_CLASSES_METHOD = `
  // ${IMAGE_CLASSES_MARKER}
  @objc(getModuleClassFromName:)
  func getModuleClassFromName(_ name: UnsafePointer<CChar>) -> AnyClass? {
    switch String(cString: name) {
    case "ImageLoader": return NSClassFromString("RCTImageLoader")
    case "ImageStoreManager": return NSClassFromString("RCTImageStoreManager")
    case "ImageEditingManager": return NSClassFromString("RCTImageEditingManager")
    case "LocalAssetImageLoader": return NSClassFromString("RCTLocalAssetImageLoader")
    case "GIFImageDecoder": return NSClassFromString("RCTGIFImageDecoder")
    default: return nil
    }
  }
`;

const withImageModuleClasses = (config) =>
  withAppDelegate(config, (cfg) => {
    const delegate = cfg.modResults;
    if (delegate.language !== "swift" || delegate.contents.includes(IMAGE_CLASSES_MARKER)) return cfg;

    const next = delegate.contents.replace(
      /(class ReactNativeDelegate: ExpoReactNativeFactoryDelegate \{\n)/,
      `$1${IMAGE_CLASSES_METHOD}`
    );
    if (next === delegate.contents) {
      console.warn("[withNativeTweaks] ReactNativeDelegate not found in AppDelegate.swift; image module classes not added");
      return cfg;
    }
    delegate.contents = next;
    return cfg;
  });

const withDynamicSplash = (config) =>
  withDangerousMod(config, [
    "android",
    (cfg) => {
      const v31StylesPath = path.join(
        cfg.modRequest.platformProjectRoot,
        "app",
        "src",
        "main",
        "res",
        "values-v31",
        "styles.xml"
      );
      if (fs.existsSync(v31StylesPath)) {
        let content = fs.readFileSync(v31StylesPath, "utf8");
        content = content.replace(
          /<item name="android:windowSplashScreenAnimatedIcon">[^<]+<\/item>/g,
          '<item name="android:windowSplashScreenAnimatedIcon">?android:attr/icon</item>'
        );
        fs.writeFileSync(v31StylesPath, content);
      }

      const stylesPath = path.join(
        cfg.modRequest.platformProjectRoot,
        "app",
        "src",
        "main",
        "res",
        "values",
        "styles.xml"
      );
      if (fs.existsSync(stylesPath)) {
        let content = fs.readFileSync(stylesPath, "utf8");
        content = content.replace(
          /<item name="android:windowSplashScreenAnimatedIcon">[^<]+<\/item>/g,
          '<item name="android:windowSplashScreenAnimatedIcon">?android:attr/icon</item>'
        );
        fs.writeFileSync(stylesPath, content);
      }
      return cfg;
    },
  ]);

module.exports = (config) =>
  withDynamicSplash(
    withImageModuleClasses(
      withIncomingCallLockscreenFlags(
        withStableDebugKeystore(withResizeableActivity(withPodfileTweaks(config)))
      )
    )
  );
